package org.pac4j.cas.config;

import org.apereo.cas.client.validation.*;
import org.pac4j.cas.client.CasProxyReceptor;
import org.pac4j.core.client.config.BaseClientConfiguration;
import org.pac4j.core.logout.handler.LogoutHandler;
import org.pac4j.core.logout.handler.DefaultLogoutHandler;
import org.pac4j.core.context.WebContext;
import org.pac4j.core.exception.TechnicalException;
import org.pac4j.core.http.url.UrlResolver;
import org.pac4j.core.util.CommonHelper;

import javax.net.ssl.HostnameVerifier;
import javax.net.ssl.SSLSocketFactory;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * CAS configuration.
 *
 * @author Jerome Leleu
 * @since 1.9.2
 */
public class CasConfiguration extends BaseClientConfiguration {

    public static final String TICKET_PARAMETER = "ticket";

    public static final String SERVICE_PARAMETER = "service";

    public final static String LOGOUT_REQUEST_PARAMETER = "logoutRequest";

    public final static String SESSION_INDEX_TAG = "SessionIndex";

    public final static String RELAY_STATE_PARAMETER = "RelayState";

    private String encoding = StandardCharsets.UTF_8.name();

    private final CasProtocolConfiguration protocolConfiguration = new CasProtocolConfiguration();

    private LogoutHandler logoutHandler;

    private CasProxyReceptor proxyReceptor;

    private String postLogoutUrlParameter = SERVICE_PARAMETER;

    /* Map containing user defined parameters */
    private Map<String, String> customParams = new HashMap<>();

    private String method;

    private final CasSecurityConfiguration securityConfiguration = new CasSecurityConfiguration();

    private final CasTicketValidatorConfiguration ticketValidatorConfiguration =
            new CasTicketValidatorConfiguration(this, securityConfiguration);

    private CasUrlConfiguration urlConfiguration = new CasUrlConfiguration();

    public CasConfiguration() {}

    public CasConfiguration(final String loginUrl) {
        this.urlConfiguration = new CasUrlConfiguration(loginUrl);
    }

    public CasConfiguration(final String loginUrl, final CasProtocol protocol) {
        this.urlConfiguration = new CasUrlConfiguration(loginUrl);
        this.protocolConfiguration.setProtocol(protocol);
    }

    public CasConfiguration(final String loginUrl, final String prefixUrl) {
        this.urlConfiguration = new CasUrlConfiguration(loginUrl, prefixUrl);
    }

    @Override
    protected void internalInit(final boolean forceReinit) {
        if (CommonHelper.isBlank(getLoginUrl()) && CommonHelper.isBlank(getPrefixUrl()) && CommonHelper.isBlank(getRestUrl())) {
            throw new TechnicalException("loginUrl, prefixUrl and restUrl cannot be all blank");
        }

        initializeClientConfiguration();

        initializeLogoutHandler();

        securityConfiguration.internalInit();
    }

    protected void initializeClientConfiguration() {
        urlConfiguration.initializeClientConfiguration();
    }

    protected void initializeLogoutHandler() {
        if (this.logoutHandler == null) {
            this.logoutHandler = new DefaultLogoutHandler();
        }
    }

    public TicketValidator retrieveTicketValidator(final WebContext context) {
        return ticketValidatorConfiguration.retrieveTicketValidator(context);
    }

    protected TicketValidator buildSAMLTicketValidator(final WebContext context) {
        return ticketValidatorConfiguration.buildSAMLTicketValidator(context);
    }

    protected void addPrivateKey(final Cas20ServiceTicketValidator validator) {
        ticketValidatorConfiguration.addPrivateKey(validator);
    }

    protected TicketValidator buildCas30ProxyTicketValidator(final WebContext context) {
        return ticketValidatorConfiguration.buildCas30ProxyTicketValidator(context);
    }

    protected TicketValidator buildCas30TicketValidator(final WebContext context) {
        return ticketValidatorConfiguration.buildCas30TicketValidator(context);
    }

    protected TicketValidator buildCas20ProxyTicketValidator(final WebContext context) {
        return ticketValidatorConfiguration.buildCas20ProxyTicketValidator(context);
    }

    protected TicketValidator buildCas20TicketValidator(final WebContext context) {
        return ticketValidatorConfiguration.buildCas20TicketValidator(context);
    }

    protected TicketValidator buildCas10TicketValidator(final WebContext context) {
        return ticketValidatorConfiguration.buildCas10TicketValidator(context);
    }

    public String getEncoding() {
        return encoding;
    }

    public void setEncoding(final String encoding) {
        this.encoding = encoding;
    }

    public String computeFinalLoginUrl(final WebContext context) {
        init();
        return urlConfiguration.computeFinalLoginUrl(context);
    }

    public String getLoginUrl() {
        return urlConfiguration.getLoginUrl();
    }

    public void setLoginUrl(final String loginUrl) {
        urlConfiguration.setLoginUrl(loginUrl);
    }

    public String getPrefixUrl() {
        return urlConfiguration.getPrefixUrl();
    }

    public String computeFinalPrefixUrl(final WebContext context) {
        init();
        return urlConfiguration.computeFinalPrefixUrl(context);
    }

    public void setPrefixUrl(final String prefixUrl) {
        urlConfiguration.setPrefixUrl(prefixUrl);
    }

    public HostnameVerifier getHostnameVerifier() {
        return securityConfiguration.getHostnameVerifier();
    }

    public void setHostnameVerifier(final HostnameVerifier hostnameVerifier) {
        securityConfiguration.setHostnameVerifier(hostnameVerifier);
    }

    public SSLSocketFactory getSslSocketFactory() {
        return securityConfiguration.getSslSocketFactory();
    }

    public void setSslSocketFactory(final SSLSocketFactory sslSocketFactory) {
        securityConfiguration.setSslSocketFactory(sslSocketFactory);
    }

    public Map<String, String> getCustomParams() {
        return customParams;
    }

    public void setCustomParams(final Map<String, String> customParams) {
        this.customParams = customParams;
    }

    public long getTimeTolerance() {
        return protocolConfiguration.getTimeTolerance();
    }

    public void setTimeTolerance(final long timeTolerance) {
        protocolConfiguration.setTimeTolerance(timeTolerance);
    }

    public CasProtocol getProtocol() {
        return protocolConfiguration.getProtocol();
    }

    public void setProtocol(final CasProtocol protocol) {
        protocolConfiguration.setProtocol(protocol);
    }

    public boolean isRenew() {
        return protocolConfiguration.isRenew();
    }

    public void setRenew(final boolean renew) {
        protocolConfiguration.setRenew(renew);
    }

    public boolean isGateway() {
        return protocolConfiguration.isGateway();
    }

    public void setGateway(final boolean gateway) {
        protocolConfiguration.setGateway(gateway);
    }

    public boolean isAcceptAnyProxy() {
        return protocolConfiguration.isAcceptAnyProxy();
    }

    public void setAcceptAnyProxy(final boolean acceptAnyProxy) {
        protocolConfiguration.setAcceptAnyProxy(acceptAnyProxy);
    }

    public ProxyList getAllowedProxyChains() {
        return protocolConfiguration.getAllowedProxyChains();
    }

    public void setAllowedProxyChains(final ProxyList allowedProxyChains) {
        protocolConfiguration.setAllowedProxyChains(allowedProxyChains);
    }

    public void setAllowedProxies(final List<String> allowedProxies) {
        protocolConfiguration.setAllowedProxies(allowedProxies);
    }

    public LogoutHandler getLogoutHandler() {
        return logoutHandler;
    }

    public LogoutHandler findLogoutHandler() {
        init();
        return logoutHandler;
    }

    public void setLogoutHandler(final LogoutHandler logoutHandler) {
        this.logoutHandler = logoutHandler;
    }

    public TicketValidator getDefaultTicketValidator() {
        return ticketValidatorConfiguration.getDefaultTicketValidator();
    }

    public void setDefaultTicketValidator(final TicketValidator defaultTicketValidator) {
        ticketValidatorConfiguration.setDefaultTicketValidator(defaultTicketValidator);
    }

    public CasProxyReceptor getProxyReceptor() {
        return proxyReceptor;
    }

    public void setProxyReceptor(final CasProxyReceptor proxyReceptor) {
        this.proxyReceptor = proxyReceptor;
    }

    public String getPostLogoutUrlParameter() {
        return postLogoutUrlParameter;
    }

    public void setPostLogoutUrlParameter(final String postLogoutUrlParameter) {
        this.postLogoutUrlParameter = postLogoutUrlParameter;
    }

    public String getRestUrl() {
        return urlConfiguration.getRestUrl();
    }

    public void setRestUrl(final String restUrl) {
        urlConfiguration.setRestUrl(restUrl);
    }

    public String computeFinalRestUrl(final WebContext context) {
        init();
        return urlConfiguration.computeFinalRestUrl(context);
    }

    public UrlResolver getUrlResolver() {
        return urlConfiguration.getUrlResolver();
    }

    public void setUrlResolver(final UrlResolver urlResolver) {
        urlConfiguration.setUrlResolver(urlResolver);
    }

    public void addCustomParam(final String name, final String value) {
        this.customParams.put(name, value);
    }

    public String getMethod() {
        return method;
    }

    public void setMethod(final String method) {
        this.method = method;
    }

    public String getPrivateKeyPath() {
        return securityConfiguration.getPrivateKeyPath();
    }

    public void setPrivateKeyPath(final String privateKeyPath) {
        securityConfiguration.setPrivateKeyPath(privateKeyPath);
    }

    public String getPrivateKeyAlgorithm() {
        return securityConfiguration.getPrivateKeyAlgorithm();
    }

    public void setPrivateKeyAlgorithm(final String privateKeyAlgorithm) {
        securityConfiguration.setPrivateKeyAlgorithm(privateKeyAlgorithm);
    }

    @Override
    public String toString() {
        return CommonHelper.toNiceString(this.getClass(), "loginUrl", this.getLoginUrl(), "prefixUrl", this.getPrefixUrl(), "restUrl", this.getRestUrl(),
                "protocol", this.getProtocol(), "renew", this.isRenew(), "gateway", this.isGateway(), "encoding", this.encoding,
                "logoutHandler", this.logoutHandler, "acceptAnyProxy", this.isAcceptAnyProxy(), "allowedProxyChains", this.getAllowedProxyChains(),
                "proxyReceptor", this.proxyReceptor, "timeTolerance", this.getTimeTolerance(), "postLogoutUrlParameter",
                this.postLogoutUrlParameter, "defaultTicketValidator", this.getDefaultTicketValidator(), "urlResolver", this.getUrlResolver(),
                "method", this.method, "privateKeyPath", this.getPrivateKeyPath(), "privateKeyAlgorithm", this.getPrivateKeyAlgorithm());
    }
}
